insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_113_v1'
from (values
('127.815.d.1.A',3,'A fabrication apprentice reports a material shortage to the shop foreman verbally, then emails the details to the supplier and the project engineer. She is demonstrating effective oral and written communication with:','["individuals from varied roles and backgrounds", "only her teammates", "only her relatives", "only the person she likes"]'::jsonb,0,'Different audiences need clear messages.','original'),
('127.815.d.1.A',4,'An email to a supplier about a late steel delivery should state:','["nothing specific", "the order number, the item and the needed date", "only that the shop is upset", "a joke about the delay"]'::jsonb,1,'Specific details get a response.','original'),
('127.815.d.1.B',3,'A welder studies a print that shows a groove weld symbol, a root opening and a bevel angle before joining two plates. He is interpreting:','["a school schedule", "a movie poster", "engineering drawings, charts, diagrams and welding symbols", "a travel map"]'::jsonb,2,'Weld symbols convey weld type and size.','original'),
('127.815.d.1.B',4,'In a welding symbol, the weld type is shown by the symbol placed:','["outside the drawing", "on the border", "on the tail only", "on the reference line"]'::jsonb,3,'The symbol sits on the reference line.','original'),
('127.815.d.1.C',3,'To lay out a pattern for a cone, a fabricator uses geometry to find the arc length and angle of the flat shape that will roll into it. She is selecting:','["algebraic and geometric principles for precision measurement and calculation", "only a guess", "only a sports play", "only art supplies"]'::jsonb,0,'Geometry guides layout.','original'),
('127.815.d.1.C',4,'The circumference of a round pipe is found with the formula:','["half of the length", "pi times the diameter", "radius minus diameter", "diameter plus radius"]'::jsonb,1,'C = πd.','original'),
('127.815.d.2.A',3,'A student flips through a machinist''s handbook for drill sizes and thread tables, and reads a tool maker''s catalog for insert grades. She is analyzing:','["a menu", "a novel", "resources such as The Machinery''s Handbook and manufacturers'' catalogs", "a comic book"]'::jsonb,2,'Reference works give shop data.','original'),
('127.815.d.2.A',4,'A machinist''s handbook is a go-to resource for:','["recipes", "travel routes", "sports statistics", "tables of dimensions, speeds, feeds and formulas"]'::jsonb,3,'Handbooks hold shop data.','original'),
('127.815.d.2.B',3,'A class compares how a coated stick electrode and a continuously fed wire electrode create a weld, noting shielding and ease of use. They are examining the theory of:','["shielded metal arc welding and gas metal arc welding", "soldering circuits", "laser printing", "gas heating of food"]'::jsonb,0,'SMAW and GMAW differ in electrode and shielding.','original'),
('127.815.d.2.B',4,'In gas metal arc welding, the weld pool is protected from air by:','["a coat of paint", "a shielding gas", "water only", "a cloth"]'::jsonb,1,'Shielding gas protects the pool.','original'),
('127.815.d.2.C',3,'A tour of a local shop shows workers cutting, bending and joining thin sheets into ductwork and cabinets. The class is examining:','["the food industry", "the textile industry", "the sheet metal industry", "the lumber industry"]'::jsonb,2,'Sheet metal makes ducts and enclosures.','original'),
('127.815.d.2.C',4,'A typical product made in a sheet metal shop is:','["clothing", "bread", "paper", "heating and cooling ductwork"]'::jsonb,3,'Ducts are sheet metal products.','original'),
('127.815.d.2.D',3,'A student reads the markings on a grinding wheel to learn the abrasive type, grit size and bond, and checks the maximum safe speed printed on it. She is examining:','["the nomenclature of abrasive wheels", "the keys of a piano", "the parts of a bicycle", "the structure of cloth"]'::jsonb,0,'Wheel markings convey type and limits.','original'),
('127.815.d.2.D',4,'The maximum operating speed marked on a grinding wheel should:','["be guessed", "never be exceeded", "be ignored", "be doubled"]'::jsonb,1,'Overspeed can burst a wheel.','original'),
('127.815.d.3.A',3,'A student uses a hacksaw, a hand file, a bench grinder and a portable drill to cut and finish a steel bracket. She is using:','["only garden tools", "only kitchen tools", "hand and power tools and equipment commonly employed in metal manufacturing", "only paint brushes"]'::jsonb,2,'Hand and power tools shape metal.','original'),
('127.815.d.3.A',4,'Before using a power grinder, a worker should wear:','["earbuds", "flip-flops", "a loose scarf", "eye and face protection"]'::jsonb,3,'Eye protection is required.','original'),
('127.815.d.3.B',3,'Used cutting oil and metal-contaminated rags are placed in labeled containers and picked up by a licensed hauler rather than being thrown away. This shows how to:','["dispose of environmentally hazardous materials used in metal manufacturing", "hide waste", "bury waste", "pour waste down a drain"]'::jsonb,0,'Hazardous waste needs proper disposal.','original'),
('127.815.d.3.B',4,'Used cutting fluid should be disposed of:','["on the ground", "through an approved hazardous waste process", "down a floor drain", "in the trash"]'::jsonb,1,'Follow environmental rules.','original'),
('127.815.d.4.A',3,'Before turning a shaft, a student chucks it in a three-jaw chuck, and before milling a plate she clamps it in a vise with parallels. They are using:','["only paint", "only tape", "work mounting procedures on appropriate machines", "only glue"]'::jsonb,2,'Proper mounting holds work securely.','original'),
('127.815.d.4.A',4,'A reason to use parallels under a part in a mill vise is to:','["speed the spindle", "make the part weaker", "hide the part", "seat the part evenly and keep it level"]'::jsonb,3,'Parallels support and level work.','original'),
('127.815.d.4.B',3,'A class rotates among a drill press, a lathe, a band saw, a surface grinder and a mill, each performing a short job on every machine. They are operating:','["machine tools such as the drill press, lathe, saw, grinder and mill", "only sewing machines", "only kitchen appliances", "only printers"]'::jsonb,0,'Machine tools shape workpieces.','original'),
('127.815.d.4.B',4,'A drill press is mostly used to:','["weld seams", "drill accurate holes", "turn long shafts", "bend sheets"]'::jsonb,1,'Drill presses make holes.','original'),
('127.815.d.4.C',3,'A student sets the lathe to cut a 1/2-13 thread on a bolt blank, turns a gentle taper on a handle and drills a center hole. She is executing:','["only painting", "only sawing", "lathe procedures such as cutting threads, turning tapers and drilling", "only sanding"]'::jsonb,2,'Lathes cut threads and tapers.','original'),
('127.815.d.4.C',4,'A taper turned on a lathe is a feature whose diameter:','["is zero", "jumps abruptly", "stays the same", "gradually changes along its length"]'::jsonb,3,'Tapers narrow gradually.','original'),
('127.815.d.4.D',3,'A student uses a vertical mill to face a block flat, cut a 45-degree bevel and mill a small groove. She is executing:','["milling procedures such as milling flat surfaces, bevels, chamfers and grooves", "lathe procedures only", "painting only", "welding only"]'::jsonb,0,'Mills shape flat features.','original'),
('127.815.d.4.D',4,'A chamfer is a feature that:','["is a hole", "angles or slopes an edge", "is a weld", "is a thread"]'::jsonb,1,'Chamfers bevel edges.','original'),
('127.815.d.5.A',3,'A student makes a straight cut with a band saw, a bevel cut with a torch and a hole with a plasma cutter in a steel plate. She is performing:','["only sanding", "only polishing", "cutting processes such as straight cuts, bevel cuts and hole cutting", "only taping"]'::jsonb,2,'Cutting processes separate metal.','original'),
('127.815.d.5.A',4,'Before cutting with an oxy-fuel torch, the area should be:','["covered with paper", "left cluttered", "sprayed with solvent", "cleared of flammable materials"]'::jsonb,3,'Fire safety first.','original'),
('127.815.d.5.B',3,'A beginner welder selects an E6013 stick electrode for a mild steel lap joint and strikes an arc on a practice plate. She is using:','["the common types of electrodes with shielded metal arc welding", "only a glue gun", "only a soldering iron", "only a stapler"]'::jsonb,0,'Choose electrodes for the job.','original'),
('127.815.d.5.B',4,'In stick welding, the flux coating on the electrode:','["adds color", "produces a shielding gas and slag", "dries the rod", "cools the arc"]'::jsonb,1,'Flux shields the weld pool.','original'),
('127.815.d.5.C',3,'A student welds a flat plate, then a horizontal joint and then a vertical joint with a wire-feed welder. She is practicing gas metal arc welding in:','["a random mix of tools", "no position", "multiple positions", "only one position"]'::jsonb,2,'Positions test skill.','original'),
('127.815.d.5.C',4,'Welding positions include flat, horizontal, vertical and:','["none", "underwater only", "upside-down only", "overhead"]'::jsonb,3,'Four basic positions.','original'),
('127.815.d.5.D',3,'An inspector gauges a fillet weld''s leg size, looks for undercut and compares the results with the American Welding Society code. She is inspecting:','["groove and fillet welds to AWS and other codes", "clothing seams", "wood joints", "paint finishes"]'::jsonb,0,'Welds are inspected to codes.','original'),
('127.815.d.5.D',4,'A visual weld inspection looks for defects such as:','["brand names", "cracks, porosity and undercut", "bright colors", "hair"]'::jsonb,1,'Visible defects.','original'),
('127.815.d.6.A',3,'A machinist calculates the center-to-center spacing of three holes using a formula and checks it with a caliper. He is using:','["cooking times", "music scales", "mathematics in precision measuring operations", "art techniques"]'::jsonb,2,'Math supports precision.','original'),
('127.815.d.6.A',4,'Three holes are spaced 2.5 inches apart. The distance from the first to the third is:','["2.5 inches", "1.25 inches", "7.5 inches", "5.0 inches"]'::jsonb,3,'2 spaces × 2.5 = 5.0.','original'),
('127.815.d.6.B',3,'A student reads a print for a machined plate showing a top view, a section view and a table of hole sizes. She is interpreting:','["engineering drawings, charts and diagrams related to the process", "a bus schedule", "a map of a park", "a menu"]'::jsonb,0,'Prints guide machining.','original'),
('127.815.d.6.B',4,'A section view on a drawing is used to show:','["the shipping label", "the inside features of a part", "the customer", "the painting plan"]'::jsonb,1,'Sections reveal interiors.','original'),
('127.815.d.7.A',3,'A student compares galvanized steel, aluminum and stainless sheet in different gauges and notes how each bends and resists rust. She is analyzing:','["types of paper", "properties of cloth", "the types, sizes and properties of sheet metal materials", "sizes of shoes"]'::jsonb,2,'Sheet materials differ.','original'),
('127.815.d.7.A',4,'A higher gauge number for sheet metal means that the sheet is:','["wider", "longer", "thicker", "thinner"]'::jsonb,3,'Gauge numbers run opposite to thickness.','original'),
('127.815.d.7.B',3,'A class learns how acetylene and oxygen burn to produce a cutting flame and how to use a neutral flame on thin sheet. They are analyzing:','["the fundamentals of oxy-fuel processes as related to sheet metal", "the fundamentals of sewing", "the fundamentals of painting", "the fundamentals of baking"]'::jsonb,0,'Oxy-fuel uses fuel gas and oxygen.','original'),
('127.815.d.7.B',4,'An oxy-fuel torch burns:','["only water", "a fuel gas with oxygen", "only air", "only oil"]'::jsonb,1,'Fuel plus oxygen.','original'),
('127.815.d.7.C',3,'A student compares using a stick electrode and a wire-feed gun on thin sheet to see which controls heat and burn-through better. She is analyzing the fundamentals of:','["sanding wood", "stitching cloth", "shielded metal arc and gas metal arc welding for sheet metal", "gluing paper"]'::jsonb,2,'Heat control matters on thin metal.','original'),
('127.815.d.7.C',4,'On thin sheet metal, a welder must be careful to avoid:','["too little air", "a lack of glare", "extra color", "burn-through from too much heat"]'::jsonb,3,'Thin metal burns through.','original'),
('127.815.d.8.A',3,'A student checks that guards are on the shear and brake, keeps fingers clear of the blade and wears gloves when handling sharp edges. She is practicing:','["safe use of equipment", "random handling", "rushed work", "careless handling"]'::jsonb,0,'Sharp edges and shears are hazards.','original'),
('127.815.d.8.A',4,'When handling sheet metal, a worker should wear gloves to:','["show style", "protect hands from sharp edges", "hold heat", "keep hands clean"]'::jsonb,1,'Sheet edges cut.','original'),
('127.815.d.8.B',3,'Scrap flux, solvent-soaked wipes and spent cleaning chemicals from the sheet metal area are placed in approved waste containers. This shows how to:','["ignore waste", "hide waste", "dispose of hazardous materials used in sheet metal manufacturing", "burn waste"]'::jsonb,2,'Proper disposal.','original'),
('127.815.d.8.B',4,'Solvent-soaked rags from a sheet metal shop should be stored in:','["an open trash can", "a plastic bag", "a cardboard box", "a labeled, closed metal container"]'::jsonb,3,'Closed metal cans reduce fire risk.','original'),
('127.815.d.9.A',3,'A student sketches a flat pattern for a box with tabs and bend lines on a sheet before cutting. She is drawing:','["simple metal layouts", "a cartoon", "a portrait", "a poster"]'::jsonb,0,'Layouts plan the cuts and bends.','original'),
('127.815.d.9.A',4,'Bend lines on a flat pattern show:','["where to paint", "where the metal will be folded", "where to weld", "where to ship"]'::jsonb,1,'Bend lines mark folds.','original'),
('127.815.d.9.B',3,'A class folds the edges of two sheets, hooks them together and flattens the joint to create a strong lap. They are constructing:','["wood joints", "fabric hems", "common sheet metal seams", "paper folds"]'::jsonb,2,'Seams join sheets.','original'),
('127.815.d.9.B',4,'A common seam used to join sheet metal pieces without welding is a:','["string seam", "paper seam", "glue seam", "Pittsburgh lock seam"]'::jsonb,3,'Pittsburgh lock is a common HVAC seam.','original'),
('127.816.d.1.A',3,'Three fitters on a pipe rack job find the pipe lengths do not match the print, so they compare notes, recheck the measurements together and agree on a fix. They are using:','["teamwork to solve problems", "working alone in silence", "waiting for the shift to end", "blaming each other"]'::jsonb,0,'Teams solve problems by pooling information.','original'),
('127.816.d.1.A',4,'On a fabrication crew, the best response to a disagreement about a cut list is to:','["skip the part", "check the print together and agree on the correct dimension", "let the loudest person decide", "cut both versions"]'::jsonb,1,'Facts from the print settle it.','original'),
('127.816.d.1.B',3,'On a weld crew, one worker schedules tasks and reports to the supervisor while the others carry out the assigned welds. These are examples of:','["unrelated hobbies", "personal nicknames", "team roles such as leader and member", "break times"]'::jsonb,2,'Leaders coordinate; members execute.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_113_v1'
from (values
('127.816.d.1.B',4,'A team leader in a fabrication shop is mainly responsible for:','["avoiding communication", "ignoring deadlines", "doing every task alone", "coordinating the work and keeping the team on schedule"]'::jsonb,3,'Leaders organize and guide.','original'),
('127.816.d.1.C',3,'A shop owner hires and promotes workers based on skills and does not treat applicants differently because of their race, sex or religion. This follows:','["Equal Employment Opportunity law", "a pricing rule", "a shipping rule", "a paint code"]'::jsonb,0,'EEO law bars job discrimination.','original'),
('127.816.d.1.C',4,'Equal Employment Opportunity laws protect workers from:','["machine noise", "discrimination in hiring and on the job", "all deadlines", "bad weather"]'::jsonb,1,'They prohibit discrimination.','original'),
('127.816.d.1.D',3,'A machinist lists the day''s jobs in order of due date, estimates how long each takes and blocks out time for setups and breaks. She is using:','["random guesses", "a coin flip", "time-management techniques to develop a work schedule", "avoidance"]'::jsonb,2,'Scheduling allocates time to tasks.','original'),
('127.816.d.1.D',4,'The best way to schedule jobs with different due dates is to:','["pick at random", "start with the longest", "start with the easiest", "order them by deadline and estimated time"]'::jsonb,3,'Deadlines drive priority.','original'),
('127.816.d.2.A',3,'A fabricator explains a delay to a customer by phone, writes a clear note to the night shift and asks a vendor for a quote in an email. She is demonstrating:','["effective communication with people from varied backgrounds", "silent work", "gossip", "mumbling"]'::jsonb,0,'Different audiences need clear messages.','original'),
('127.816.d.2.A',4,'When handing a job off to the next shift, a worker should leave:','["a vague hint", "a clear written note on status and next steps", "no information", "only a smile"]'::jsonb,1,'Written notes prevent errors.','original'),
('127.816.d.2.B',3,'A supervisor hands a technician a work order listing the part number, quantity, material and due date. The technician checks off each step as it is finished. This shows how to:','["skip steps", "lose paperwork", "successfully complete work orders", "guess the quantity"]'::jsonb,2,'Work orders track tasks.','original'),
('127.816.d.2.B',4,'A work order for a batch of brackets usually lists:','["the weather forecast", "the lunch menu", "the worker''s hobbies", "the part number, quantity and due date"]'::jsonb,3,'It defines the job.','original'),
('127.816.d.2.C',3,'A shop estimates a welding job at 12 hours and charges $45 per hour for labor. To find the labor cost, the estimator uses the formula:','["labor cost = hours × hourly rate", "labor cost = hours − rate", "labor cost = rate ÷ hours", "labor cost = hours + rate"]'::jsonb,0,'Cost is hours times rate.','original'),
('127.816.d.2.C',4,'A job takes 12 hours of labor at $45 per hour. The labor cost is:','["$480", "$540", "$600", "$57"]'::jsonb,1,'12 × 45 = 540.','original'),
('127.816.d.2.D',3,'A welder reads a detailed fabrication print with a section view, weld symbols, a bill of materials and tolerance notes before assembling a frame. She is interpreting:','["a bus schedule", "a recipe", "advanced engineering drawings, charts, diagrams and welding symbols", "a comic strip"]'::jsonb,2,'Advanced prints guide assembly.','original'),
('127.816.d.2.D',4,'A bill of materials on a fabrication print lists:','["the workers'' names", "the customer''s address", "the shop''s profits", "the parts and quantities needed"]'::jsonb,3,'BOM lists parts.','original'),
('127.816.d.2.E',3,'A machinist uses algebra to find the diameter of a hole that is 0.050 inch larger than a 0.625-inch pin. He is demonstrating:','["calculation for precision measuring operations using algebra", "rough sketching", "paint mixing", "guessing"]'::jsonb,0,'Algebra supports precise sizing.','original'),
('127.816.d.2.E',4,'A hole must be 0.050 inch larger than a 0.625-inch pin. The hole diameter is:','["0.600 inch", "0.675 inch", "0.575 inch", "0.725 inch"]'::jsonb,1,'0.625 + 0.050 = 0.675.','original'),
('127.816.d.3.A',3,'A student checks welding code books, material specification sheets and a safety data sheet before choosing a filler metal. She is analyzing:','["a novel", "a sports page", "resources found in various manufacturing reference materials", "a game guide"]'::jsonb,2,'Reference materials give authoritative data.','original'),
('127.816.d.3.A',4,'A material specification sheet tells a fabricator the metal''s:','["owner''s name", "paint trend", "delivery driver", "grade, strength and composition"]'::jsonb,3,'Specs describe the material.','original'),
('127.816.d.3.B',3,'A student shows how a plasma torch, a TIG torch and a wire-feed gun each form a joint and where each is best used. She is demonstrating knowledge of:','["the various welding processes", "sewing methods", "baking methods", "painting methods"]'::jsonb,0,'Different processes suit different jobs.','original'),
('127.816.d.3.B',4,'Gas tungsten arc welding (TIG) is often chosen for:','["rough outdoor repairs only", "clean, precise welds on thin material", "driving nails", "cutting wood"]'::jsonb,1,'TIG gives control.','original'),
('127.816.d.3.C',3,'A class visits a sheet metal contractor and sees how drawings turn into flat patterns, then into folded and seamed ducts. They are examining:','["the dairy industry", "the fishing industry", "the sheet metal industry", "the movie industry"]'::jsonb,2,'Sheet metal trades make ducts and enclosures.','original'),
('127.816.d.3.C',4,'One career in the sheet metal industry is a:','["lifeguard", "pastry chef", "pilot", "duct fabricator"]'::jsonb,3,'Fabricators build ducts.','original'),
('127.816.d.3.D',3,'A student compares aluminum oxide, silicon carbide and ceramic grinding wheels for a stainless job and a hardened tool steel job. She is examining:','["the advanced use of abrasives", "watercolor paints", "yarns", "wood stains"]'::jsonb,0,'Abrasive choice depends on material.','original'),
('127.816.d.3.D',4,'A grinding wheel with a higher grit number is:','["heavier", "finer and leaves a smoother finish", "coarser and rougher", "wider"]'::jsonb,1,'Higher grit means finer.','original'),
('127.816.d.4.A',3,'A student sets up a MIG welder, a plasma cutter and a surface grinder and runs a short job on each under supervision. She is operating:','["a microwave", "a printer", "various welding machines, cutting equipment and grinding equipment", "a camera"]'::jsonb,2,'Hands-on machine operation.','original'),
('127.816.d.4.A',4,'Before striking an arc on a welding machine, a welder checks:','["the music playlist", "the clock only", "the TV schedule", "that the ground clamp is attached and the area is clear of flammables"]'::jsonb,3,'Ground and fire safety.','original'),
('127.816.d.4.B',3,'A class watches a CNC machine cut a program of holes and slots automatically after a student loads the code and sets the work zero. They are demonstrating knowledge of:','["computer numerical control (CNC) machines", "hand cranks only", "bicycle pedals", "kitchen mixers"]'::jsonb,0,'CNC follows coded instructions.','original'),
('127.816.d.4.B',4,'A CNC machine moves its tool according to:','["random vibration", "a coded program", "the room light", "the operator''s mood"]'::jsonb,1,'Programmed instructions control motion.','original'),
('127.816.d.4.C',3,'A robotic welding cell repeats the same weld path on every frame while a human loads the parts. The class is demonstrating knowledge of:','["manual hammering only", "hand painting", "automated welding machines", "hand sewing"]'::jsonb,2,'Automation repeats welds consistently.','original'),
('127.816.d.4.C',4,'A key benefit of an automated welding cell is:','["random weld paths", "slower output", "no setup needed", "consistent weld quality on repetitive jobs"]'::jsonb,3,'Repeatability.','original'),
('127.816.d.4.D',3,'A student researches laser cutting, additive manufacturing and collaborative robots to see how they could change a metal shop in the next ten years. She is demonstrating knowledge of:','["emerging technologies that may affect metal manufacturing", "weather", "old tools only", "traditional crafts only"]'::jsonb,0,'New technology changes industry.','original'),
('127.816.d.4.D',4,'A 3D metal printer builds a part by:','["bending only", "adding material layer by layer", "pouring into a mold only", "cutting only"]'::jsonb,1,'Additive manufacturing.','original'),
('127.816.d.4.E',3,'A shop sends used coolant, spent solvents and contaminated filters to a certified waste hauler instead of the dumpster. This shows how to:','["hide waste", "burn waste", "dispose of environmentally hazardous materials associated with the equipment", "dump waste"]'::jsonb,2,'Proper disposal of hazardous waste.','original'),
('127.816.d.4.E',4,'Information on the hazards of a cutting fluid and how to dispose of it is found on its:','["price tag", "shipping label", "brand logo", "safety data sheet (SDS)"]'::jsonb,3,'SDS gives hazard and disposal info.','original'),
('127.816.d.5.A',3,'A student clamps round stock in a collet, secures a block in a vise and bolts a casting to a rotary table. She is using:','["work mounting procedures on appropriate machines", "only tape", "only glue", "only magnets for everything"]'::jsonb,0,'Proper holding for each part.','original'),
('127.816.d.5.A',4,'A rigid setup matters when holding work because a loose part can:','["cool the tool", "move or fly out during cutting", "look nicer", "cut faster"]'::jsonb,1,'Work-holding safety.','original'),
('127.816.d.5.B',3,'A class compares drilling, turning, sawing and grinding to decide which operation removes the most stock and which gives the smoothest finish. They are examining:','["sweeping operations", "filing operations", "cutting operations such as drill press, lathe, saw and grinder", "painting operations"]'::jsonb,2,'Different operations suit different goals.','original'),
('127.816.d.5.B',4,'Of these, the operation that usually gives the smoothest surface finish is:','["flame cutting", "rough drilling", "sawing", "grinding"]'::jsonb,3,'Grinding refines surfaces.','original'),
('127.816.d.5.C',3,'A student cuts external threads on a shaft, turns a 3-degree taper and uses a reamer to finish a hole to size on the lathe. She is executing:','["lathe procedures such as cutting threads, turning tapers, drilling and reaming", "painting steps only", "welding steps only", "sewing steps only"]'::jsonb,0,'Lathe operations.','original'),
('127.816.d.5.C',4,'A reamer is used to:','["weld a joint", "finish a drilled hole to an accurate size", "bend a bar", "cut external threads"]'::jsonb,1,'Reamers refine holes.','original'),
('127.816.d.5.D',3,'A student mills the top of a block flat, cuts a 45-degree bevel on its edge, adds a chamfer and mills a keyseat in a shaft. She is milling:','["glass panes", "fabric swatches", "flat surfaces, bevels, chamfers, grooves and key-seats", "wood planks only"]'::jsonb,2,'Mill features.','original'),
('127.816.d.5.D',4,'A keyseat is a slot cut in a shaft to hold:','["a nail", "a light bulb", "a battery", "a key that locks a pulley or gear in place"]'::jsonb,3,'Keys transmit torque.','original'),
('127.816.d.5.E',3,'A student turns a shaft to within 0.001 inch of the print and mills a plate with flatness held to a few thousandths. She is machining:','["precision pieces", "paper pieces", "rough pieces only", "decorative pieces only"]'::jsonb,0,'Precision work meets tolerances.','original'),
('127.816.d.5.E',4,'A precision part is one that is made:','["as fast as possible regardless of size", "to tight tolerances that meet the print", "in any size", "without measuring"]'::jsonb,1,'Tolerance defines precision.','original'),
('127.816.d.6.A',3,'A student cuts a plate with an oxy-fuel torch and then with a plasma cutter and compares the edge quality. She is demonstrating:','["baking processes", "printing processes", "cutting processes such as oxy-fuel and plasma", "sewing processes"]'::jsonb,2,'Different cutting processes.','original'),
('127.816.d.6.A',4,'A plasma cutter is able to cut:','["only glass", "only plastic", "only wood", "any electrically conductive metal"]'::jsonb,3,'Plasma needs conductive metal.','original'),
('127.816.d.6.B',3,'A student picks an E7018 low-hydrogen electrode for a structural joint, sets the amperage and lays a bead with the stick welder. She is demonstrating:','["the use of common electrodes with shielded metal arc welding", "glue use", "hand soldering", "taping"]'::jsonb,0,'Electrodes are chosen for the application.','original'),
('127.816.d.6.B',4,'The numbers in an electrode designation such as E7018 indicate its:','["price", "tensile strength and usage characteristics", "color", "length only"]'::jsonb,1,'E70 = 70,000 psi.','original'),
('127.816.d.6.C',3,'A student welds a joint with a stick welder, a wire-feed welder and a TIG torch, adjusting settings for each process. She is using:','["only a stapler", "only a soldering iron", "shielded metal arc, gas metal arc and gas tungsten arc welding", "only a glue gun"]'::jsonb,2,'Three common arc processes.','original'),
('127.816.d.6.C',4,'Of the three, the process that uses a non-consumable tungsten electrode is:','["wire-feed welding", "stick welding", "soldering", "gas tungsten arc welding"]'::jsonb,3,'TIG uses tungsten.','original'),
('127.816.d.6.D',3,'An inspector checks completed welds for size, cracks, porosity and fusion against the American Welding Society and Canadian Welding Bureau codes. She is inspecting:','["welds to AWS, CWB and other codes", "woodwork", "tile work", "paintwork"]'::jsonb,0,'Codes define acceptable welds.','original'),
('127.816.d.6.D',4,'Porosity in a weld looks like:','["a smooth shine", "small gas holes in the weld metal", "a bright color", "tight ripples"]'::jsonb,1,'Gas pockets form pores.','original'),
('127.816.d.7.A',3,'A shop estimates a sheet metal job at 20 hours of labor and a $38 hourly rate. She is estimating:','["paint colors", "lunch costs", "labor costs", "weather costs"]'::jsonb,2,'Labor = hours × rate.','original'),
('127.816.d.7.A',4,'Twenty hours at $38 per hour gives a labor cost of:','["$680", "$58", "$800", "$760"]'::jsonb,3,'20 × 38 = 760.','original'),
('127.816.d.7.B',3,'A machinist uses trigonometry to find the length of a hypotenuse for an angled brace and checks it with a gauge. He is using:','["advanced mathematics in precision measuring operations", "art projects", "stories", "guesses"]'::jsonb,0,'Trig supports precision.','original'),
('127.816.d.7.B',4,'A brace forms a right triangle with legs of 3 inches and 4 inches. The length of the brace is:','["12 inches", "5 inches", "7 inches", "6 inches"]'::jsonb,1,'3-4-5.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_113_v1'
from (values
('127.816.d.7.C',3,'A fabricator reads an industrial blueprint with title block, revision table, hidden lines and a notes section before cutting steel. She is interpreting:','["a train schedule", "a lunch menu", "industrial standard blueprints, drawings, charts and diagrams", "a map of a mall"]'::jsonb,2,'Blueprints guide fabrication.','original'),
('127.816.d.7.C',4,'The revision table on a blueprint tells the reader:','["the price", "the shop''s address", "the weather", "what has changed since earlier versions"]'::jsonb,3,'Revisions track changes.','original'),
('127.816.d.8.A',3,'A student compares galvanized steel, stainless, aluminum and the rivets, bolts and screws used to join them. She is analyzing:','["properties of sheet metal materials and fasteners", "wood grains", "fabric swatches", "paper types"]'::jsonb,0,'Materials and fasteners.','original'),
('127.816.d.8.A',4,'A reason to use stainless sheet instead of plain steel in a food kitchen is that stainless:','["is paper thin", "resists rust and is easy to clean", "rusts quickly", "is soft like wax"]'::jsonb,1,'Corrosion resistance.','original'),
('127.816.d.8.B',3,'A class studies how an oxygen-acetylene cutting torch can trim sheet metal and what flame settings protect thin material. They are analyzing:','["inkjet processes", "sewing processes", "oxy-fuel processes as related to sheet metal", "baking processes"]'::jsonb,2,'Oxy-fuel on sheet.','original'),
('127.816.d.8.B',4,'To avoid warping thin sheet while cutting with a torch, a worker should:','["stop and stay", "remove all shielding", "use the largest tip", "use a small tip and travel quickly"]'::jsonb,3,'Less heat input.','original'),
('127.816.d.8.C',3,'A class compares stick, wire-feed and TIG methods for joining sheet metal and explains which gives the least distortion. They are demonstrating knowledge of:','["shielded metal arc, gas metal arc and gas tungsten arc welding for sheet metal", "glue types", "yarn types", "paint types"]'::jsonb,0,'Welding choices for sheet.','original'),
('127.816.d.8.C',4,'For welding very thin sheet with minimal distortion, a good choice is:','["a torch cut", "gas tungsten arc welding with low heat", "a heavy stick electrode", "a hammer weld"]'::jsonb,1,'TIG gives precise heat control.','original'),
('127.816.d.9.A',3,'Before running the box and pan brake, a student checks the guards, keeps hands clear of the clamping area and wears gloves. She is:','["working carelessly", "ignoring rules", "using equipment commonly employed in sheet metal safely", "rushing"]'::jsonb,2,'Safe operation of sheet metal equipment.','original'),
('127.816.d.9.A',4,'A power shear should be operated only:','["while talking on a phone", "without training", "with the guard removed", "with guards in place and hands clear of the blade"]'::jsonb,3,'Guards prevent injuries.','original'),
('127.816.d.9.B',3,'A shop collects used solder flux, spent solvents and oily rags from the sheet metal area in approved waste containers. This shows how to:','["dispose of environmentally hazardous materials used in sheet metal manufacturing", "hide waste", "dump waste", "burn waste"]'::jsonb,0,'Environmental compliance.','original'),
('127.816.d.9.B',4,'Used solvent from cleaning sheet metal should be:','["poured outdoors", "collected in a labeled container for proper disposal", "poured in the sink", "thrown in trash"]'::jsonb,1,'Hazardous waste.','original'),
('127.816.d.9.C',3,'A student researches how laser cutters, automatic bending machines and robot arms are changing sheet metal shops. She is demonstrating knowledge of:','["painting", "old craft methods only", "emerging technologies that may affect sheet metal manufacturing", "cooking"]'::jsonb,2,'New technology in sheet metal.','original'),
('127.816.d.9.C',4,'A fiber laser cutter can cut sheet metal:','["only by chance", "only with a hammer", "only by hand", "quickly and precisely from a digital file"]'::jsonb,3,'Automation increases precision.','original'),
('127.816.d.10.A',3,'A student draws a flat pattern for a rectangular-to-round transition using parallel line and triangulation methods. She is drawing:','["advanced sheet metal layouts", "a cartoon", "a portrait", "a doodle"]'::jsonb,0,'Advanced layouts use triangulation.','original'),
('127.816.d.10.A',4,'Triangulation is a pattern development method used for:','["nothing", "transition fittings between different shapes", "round cans only", "simple flat boxes only"]'::jsonb,1,'Transitions are triangulated.','original'),
('127.816.d.10.B',3,'A class forms a grooved seam, a standing seam and a Pittsburgh lock on practice sheets and compares their strength. They are constructing:','["fabric seams", "wood joints", "sheet metal seams", "paper creases"]'::jsonb,2,'Different seams for different uses.','original'),
('127.816.d.10.B',4,'A standing seam is commonly used on:','["T-shirts", "paper cups", "bicycles", "metal roofing"]'::jsonb,3,'Standing seam roofs.','original'),
('127.816.d.10.C',3,'A student lays out and builds a fitting that changes a duct from square to round and another that jogs the duct sideways around a beam. She is constructing:','["transitions and offsets", "pillows", "birdhouses", "paper planes"]'::jsonb,0,'Duct fittings.','original'),
('127.816.d.10.C',4,'An offset fitting in a duct run is used to:','["block air", "shift the duct around an obstruction", "increase noise", "add color"]'::jsonb,1,'Offsets bypass obstacles.','original'),
('127.816.d.10.D',3,'A student uses a TIG torch with a filler rod to join thin stainless panels into a small box without warping them. She is using:','["a hot iron", "a glue gun", "the gas tungsten arc welding process in sheet metal construction", "a stapler"]'::jsonb,2,'TIG on sheet.','original'),
('127.816.d.10.D',4,'A shielding gas commonly used with TIG welding is:','["oxygen only", "hydrogen only", "air only", "argon"]'::jsonb,3,'Argon shields the weld.','original'),
('127.816.d.10.E',3,'A student applies layout, cutting, forming, seaming and welding to build a ventilation hood from sheet steel to a print. She is applying:','["the principles of sheet metal construction to fabrication of a project", "a puzzle", "a cooking recipe", "a drawing contest"]'::jsonb,0,'Combine skills for a project.','original'),
('127.816.d.10.E',4,'When building a project from a print, a fabricator should always:','["guess dimensions", "verify dimensions against the drawing before cutting", "skip the print", "cut first"]'::jsonb,1,'Check before you cut.','original'),
('127.816.d.10.F',3,'A student logs her sheet metal projects and skills in a portfolio and practices them on a job-shadow day at a local shop. She is applying:','["gaming skills only", "sports skills only", "sheet metal skills to career preparation learning experiences", "cooking skills only"]'::jsonb,2,'Skills are practiced in career settings.','original'),
('127.816.d.10.F',4,'A portfolio of completed fabrication projects helps a job applicant by:','["replacing a resume", "hiding her abilities", "avoiding interviews", "showing employers what skills she has"]'::jsonb,3,'Evidence of skill.','original')
